svg:
MIRoKIT – Kultur- und Spieltriathlon
Эмблема MIRoKIT с русской дуговой надписью, голубым глобусом, книгой, шахматной фигурой, бегущим человеком, логотипом и лентой.


                               d="M230 1040 C390 1091 492 1120 620 1127 C800 1137 969 1090 1093 1032"

  01 · Emblemhintergrund
  Внешний тёмно-синий силуэт и светлая основа эмблемы.




  02 · Globusflächen
  Разделённые синие области глобуса и небольшие цветовые детали.












  03 · Offenes Buch
  Красная обложка и две светлые страницы книги.






  04 · Läufer
  Фигура бегущего человека, включая голову и мелкие детали.





  05 · Schachfigur
  Красный шахматный конь, светлый глаз и основание фигуры.





  06 · MIRoKIT-Schriftzug
  Векторный красный кириллический надписной логотип МИРоКИТ.











  07 · Bogenüberschrift
  Контурные буквы надписи КУЛЬТУРНО-ИГРОВОЙ ТРИАТЛОН, включая внутренние просветы и мелкие детали.















































  08 · Unteres Banner
  Das leere untere Schriftband mit Grundfläche, gefalteten Enden und Abschlussdetails.

    Bannerfläche
    Helle Außenform und dunkelblaue Innenfläche des Banners.









    Bannerfalten
    Die beiden gefalteten Bannerenden und ihre Innenflächen.






    Bannerkontur und Details
    Kleine Kontur-, Kanten- und Abschlussdetails des Banners.










    Aktuelle Projekte



  (() => {
    const labels = {
      about_us_page: { ru: "Что такое МИРоКИТ", en: "What is MIRoKIT", de: "Was ist MIRoKIT" },
      history_of_the_game_page: { ru: "История игры", en: "History of the Game", de: "Geschichte des Spiels" },
      our_team_page: { ru: "Наша команда", en: "Our Team", de: "Unser Team" },
      world_page: { ru: "МИРоКИТ в мире", en: "MIRoKIT Worldwide", de: "MIRoKIT weltweit" },
      our_partners_page: { ru: "Наши партнёры", en: "Our Partners", de: "Unsere Partner" },
      principle_of_the_game_page: { ru: "Принцип игры", en: "Game Principle", de: "Spielprinzip" },
      how_to_participate_page: { ru: "Как участвовать", en: "How to Participate", de: "So funktioniert's" },
      age_groups_page: { ru: "Возрастные группы", en: "Age Groups", de: "Altersgruppen" },
      current_projects_page: { ru: "Текущие проекты", en: "Current Projects", de: "Aktuelle Projekte" },
      news_page: { ru: "Новости", en: "News", de: "News" },
      gallery_page: { ru: "Галерея", en: "Gallery", de: "Galerie" },
      contact_form_page: { ru: "Контактная форма", en: "Contact Form", de: "Kontaktformular" },
      contact_liga_admission_form_page: { ru: "Вступление в Лигу", en: "League Admission", de: "Liga-Beitritt" }
    };
    const pastLabels = { ru: "Завершённые проекты", en: "Past Projects", de: "Vergangene Projekte" };
    const svgNamespace = "http://www.w3.org/2000/svg";
    const curvePath = document.getElementById("footer-ribbon-text-curve");
    const curveData = curvePath?.getAttribute("d");
    const frame = window.frameElement;

    if (!frame || !curveData) return;

    let projectView = "current_projects";
    const parentDocument = window.parent.document;
    const parentWindow = window.parent;

    function makeSvgElement(name, attributes = {}) {
      const element = parentDocument.createElementNS(svgNamespace, name);
      Object.entries(attributes).forEach(([key, value]) => element.setAttribute(key, value));
      return element;
    }

    function buildSharedArtwork() {
      const sprite = makeSvgElement("svg", {
        "aria-hidden": "true",
        focusable: "false",
        width: "0",
        height: "0",
        class: "section-logo-sprite"
      });
      const definitions = makeSvgElement("defs");
      const symbol = makeSvgElement("symbol", {
        id: "mirokit-section-logo-symbol",
        viewBox: document.documentElement.getAttribute("viewBox") || "0 0 1316 1195"
      });

      Array.from(document.documentElement.children)
        .filter((child) => child.localName === "g")
        .forEach((group) => {
          const artwork = parentDocument.importNode(group, true);
          artwork.querySelectorAll("text").forEach((text) => text.remove());
          symbol.append(artwork);
        });

      definitions.append(symbol);
      sprite.append(definitions);
      parentDocument.body.prepend(sprite);
    }

    function makeLogo(container, index) {
      const logoKey = container.dataset.logoKey;
      const definition = labels[logoKey];
      if (!definition) return null;

      const logo = makeSvgElement("svg", {
        class: "section-logo-object",
        viewBox: "0 0 1316 1195",
        preserveAspectRatio: "xMidYMid meet",
        role: "img"
      });
      const title = makeSvgElement("title", { id: `section-logo-title-${index}` });
      const use = makeSvgElement("use", { href: "#mirokit-section-logo-symbol" });
      const definitions = makeSvgElement("defs");
      const curveId = `section-logo-curve-${index}`;
      const curve = makeSvgElement("path", { id: curveId, d: curveData, fill: "none" });
      const textNode = makeSvgElement("text", {
        fill: "#ffffff",
        "font-family": "Montserrat, Arial, Helvetica, sans-serif",
        "font-size": "82",
        "font-weight": "800",
        "text-anchor": "middle",
        "text-rendering": "geometricPrecision"
      });
      const textPath = makeSvgElement("textPath", { href: `#${curveId}`, startOffset: "50%" });

      logo.setAttribute("aria-labelledby", title.id);
      definitions.append(curve);
      textNode.append(textPath);
      logo.append(title, definitions, use, textNode);
      container.replaceChildren(logo);

      const maxTextLength = curve.getTotalLength() - 44;

      function fitText(preferredSize) {
        textNode.setAttribute("font-size", preferredSize);
        textPath.removeAttribute("textLength");
        textPath.removeAttribute("lengthAdjust");

        const fit = () => {
          let size = preferredSize;
          while (textNode.getComputedTextLength() > maxTextLength && size > 30) {
            size -= 2;
            textNode.setAttribute("font-size", size);
          }
          if (textNode.getComputedTextLength() > maxTextLength) {
            textPath.setAttribute("textLength", maxTextLength);
            textPath.setAttribute("lengthAdjust", "spacingAndGlyphs");
          }
        };

        parentWindow.requestAnimationFrame(fit);
        if (parentDocument.fonts?.ready) parentDocument.fonts.ready.then(fit).catch(() => {});
      }

      function update(language = parentDocument.documentElement.lang) {
        const lang = definition[language] ? language : "en";
        const text = logoKey === "current_projects_page" && projectView === "pas_projects"
          ? pastLabels[lang]
          : definition[lang];
        textPath.textContent = text;
        title.textContent = `MIRoKIT — ${text}`;
        logo.setAttribute("aria-label", `MIRoKIT — ${text}`);
        fitText(lang === "en" ? 82 : 74);
      }

      return update;
    }

    function initializeLogos() {
      if (parentDocument.getElementById("mirokit-section-logo-symbol")) return;
      buildSharedArtwork();

      const logoUpdates = Array.from(parentDocument.querySelectorAll(".section-logo[data-logo-key]"))
        .map(makeLogo)
        .filter(Boolean);

      parentDocument.addEventListener("mirokit:languagechange", (event) => {
        logoUpdates.forEach((update) => update(event.detail?.lang));
      });
      parentDocument.addEventListener("mirokit:projectviewchange", (event) => {
        projectView = event.detail?.viewKey === "pas_projects" ? "pas_projects" : "current_projects";
        logoUpdates.forEach((update) => update());
      });

      projectView = parentDocument.querySelector(".projects-switch-btn.is-active")?.dataset.linkKey === "pas_projects"
        ? "pas_projects"
        : "current_projects";
      logoUpdates.forEach((update) => update());
    }

    if (parentDocument.readyState === "loading") {
      parentDocument.addEventListener("DOMContentLoaded", initializeLogos, { once: true });
    } else {
      initializeLogos();
    }
  })();
